<script lang="ts">
  let {operation,scenarioId,context,turnIndex=0,conditionId=''}:{operation:string;scenarioId:string;context:Record<string,any>|null;turnIndex?:number;conditionId?:string}=$props();
  const notes=$derived.by(()=>{
    const data=context?.context||{},trace=context?.trace,cfg=data['framework-config.json'];
    if(conditionId&&(data['routing-comparison.json']?.conditions||[]).some((c:Record<string,any>)=>c.condition_id===conditionId))return [];
    if(!trace)return [];
    const turns=data['fabric-invocations.json']||[],native=turns.find((r:Record<string,any>)=>r.public_turn===turnIndex+1);
    const app=data['application-turns.json']?.find((r:Record<string,any>)=>r.public_turn===turnIndex+1);
    const sim=data['usersim-setup.json'],events=data['fabric-lifecycle.jsonl']||[];
    switch(operation){
      case 'persona.source':return trace.source_lock?[`The selected original came from ${trace.source_lock.source==='ngc'?'Singapore NGC Extended':'public HF profile-only'}, revision ${trace.source_lock.source_revision}.`]:[];
      case 'persona.lock':return trace.source_lock?[`The selection receipt retains the original content identity. The full person is shown in Step 1; this operation verifies that same original rather than choosing another person.`]:[];
      case 'usersim.prepare':return sim?[`Resolved preparation selects ${sim.probe}, locale ${sim.configuration.locale} and a maximum of ${sim.configuration.max_turns} public turns. This records preparation; generation is observed in the loop operation.`]:[];
      case 'usersim.finalize':return sim?[`The native outcome contains ${sim.outcome.n_turns} public turns, ${sim.outcome.warning_count} warnings and ${sim.outcome.n_assistant_inline_failures||0} in-loop assistant-quality flags. No post-loop UserSim evaluation dataset or dashboard was generated by this run.`]:[];
      case 'fabric.config':return cfg?[`The saved configuration selects ${cfg.harness.adapter_id} with ${cfg.harness.resolution} resolution. Its runtime accepts ${cfg.runtime.input_schema} input and requests ${cfg.runtime.output_schema} output; ${cfg.runtime.max_turns} is an internal execution limit, separate from public learner turns.`]:[];
      case 'fabric.plan':return data['fabric-doctor.json']?[`Preflight returned ${data['fabric-doctor.json'].status}. That is the setup result to compare before starting the runtime; it does not certify a later response.`]:[];
      case 'fabric.start':return events.some((e:Record<string,any>)=>e.event==='runtime_started')?[`The lifecycle contains a runtime-started event. ${turns.length} actual native invocations were subsequently recorded in that persistent runtime.`]:[];
      case 'fabric.invoke':return app?[`Selected public turn ${turnIndex+1} was answered by the application's clarification branch. No RunRequest was submitted for this turn.`]:native?[`Selected public turn ${turnIndex+1} has one recorded Fabric invocation${native.invocation_sequence?`, native sequence ${native.invocation_sequence}`:''}. Its terminal runtime status is ${native.runtime_status}.`]:['No invocation has been associated with the selected public turn in this recording.'];
      case 'fabric.result':return app?['This turn has a confirmed application response rather than a normalized Fabric result.']:native?[`Fabric returned ${native.runtime_status}; application answer validation recorded ${native.outcome?.status||'no status'}. ${native.output?.native_response_published===false?'The native proposal and the source-based delivered reply are separate records.':'The public response is derived from the normalized output.'}`]:[];
      case 'harness.context':case 'mcp.connect':return cfg?[`The configured execution allowlist contains ${cfg.tools.enabled.join(', ')}. Connection/discovery establishes availability; only native tool events establish that one of these tools was actually called.`]:[];
      case 'mcp.search':case 'mcp.details':case 'mcp.compare':{
        const name=operation==='mcp.search'?'search_courses':operation==='mcp.details'?'get_course_details':'compare_courses';
        const tools=(trace.tools||[]).filter((t:Record<string,any>)=>t.name?.endsWith(name));
        return tools.length?[`${tools.length} ${name} event${tools.length===1?' is':'s are'} retained in this run. Step 5 interprets the returned facts for the selected public turn; the native record preserves arguments and the complete result.`]:[`The ${name} tool was available, but no call to it is recorded in this scenario.`];
      }
      case 'relay.configure':return cfg?[`Relay is ${cfg.relay.enabled?'enabled':'disabled'}; full-payload instrumentation is ${cfg.relay.observability.enable_full_payloads?'enabled':'disabled'}. Export used the native file sink, without a Phoenix or collector session.`]:[];
      case 'relay.scopes':return [`The run retains ${trace.relay?.scopes?.length||0} native scopes. Their parent IDs describe the observed harness execution; gateway accounting has separate identities.`];
      case 'helix.job':return data['helix-job.json']?[`The durable job status is ${data['helix-job.json'].status}. Its result belongs to saved criterion scoring, separate from generating another advisor response.`]:[];
      case 'openshell.probe':return data['boundary-probes.json']?[`The standalone probes recorded ${(data['boundary-probes.json'].probes||[]).filter((p:Record<string,any>)=>p.denied).length} denied operations. Cleanup ${data['cleanup.json']?.native_absence_confirmed?'confirmed that the owned sandbox was absent':'is not confirmed in this recording'}.`]:[];
      default:return [];
    }
  });
</script>

{#if notes.length}<section class="recorded-operation" aria-label="Observed operation result">{#each notes as note}<p>{note}</p>{/each}</section>{/if}
<style>.recorded-operation{border-left:2px solid var(--teal);padding:1px 14px;margin:18px 0;font-size:12px;line-height:1.7;background:#f2f8f6}</style>
